/*
 * Minimal EDS bootstrap script.
 * In a real aem.live project this file is generated by the boilerplate
 * (via `npm init @adobe/helix-project`) and wires up block loading,
 * lazy-loading, and the eager/lazy/delayed phases. It's trimmed here
 * to keep this demo focused on the block code itself.
 */

async function loadBlock(block) {
  const name = block.dataset.blockName;
  if (!name) return;
  try {
    const mod = await import(`../blocks/${name}/${name}.js`);
    const cssLoaded = new Promise((resolve) => {
      const link = document.createElement('link');
      link.rel = 'stylesheet';
      link.href = `../blocks/${name}/${name}.css`;
      link.onload = resolve;
      link.onerror = resolve;
      document.head.append(link);
    });
    await Promise.all([cssLoaded, mod.default(block)]);
    block.dataset.blockStatus = 'loaded';
  } catch (err) {
    // eslint-disable-next-line no-console
    console.error(`Failed to load block: ${name}`, err);
  }
}

function decorateBlocks(main) {
  main.querySelectorAll('[data-block-name]').forEach(loadBlock);
}

document.addEventListener('DOMContentLoaded', () => {
  const main = document.querySelector('main');
  if (main) decorateBlocks(main);
});
